INSERT INTO football.fixture_markets (fixture_id, market_id, outcomes) SELECT f.id, pm.id, CASE pm.slug WHEN '1x2' THEN '["Home","Draw","Away"]'::jsonb WHEN 'btts' THEN '["Yes","No"]'::jsonb WHEN 'over-under-2-5' THEN '["Over 2.5","Under 2.5"]'::jsonb END FROM football.fixtures f CROSS JOIN football.prediction_markets pm WHERE f.competition_id = 'bd3c9c62-3a1b-4c24-832f-4bfdbe1f9d36' AND pm.slug IN ('1x2','btts','over-under-2-5') ON CONFLICT DO NOTHING;
